    let targetMinute = 0;
    if (id === "news-live-1") targetMinute = 180;      // USA CPI (Hour 3)
    else if (id === "news-live-2") targetMinute = 360; // UK CPI (Hour 6)
    else if (id === "news-live-3") targetMinute = 540; // US Unemployment Rate (Hour 9)
    else if (id === "news-live-4") targetMinute = 0;   // CME Bitcoin Expiry (Hour 0)

